const b=$input.first().json.body||$input.first().json;
const msg=b.message||{};
const text=msg.text||msg.caption||'';
const chatId=msg.chat?msg.chat.id:null;
// 2 ต.ค. 69: คำตอบรีวิวคลิป Veo — user ตอบกลับ (reply) ข้อความคลิปที่มี '#veo <id>' บรรทัดแรก ว่า โพสต์/ไม่ → deal-video /publish หรือ /discard (คลิปเก็บอยู่ /tiktok/pending)
const rep = msg.reply_to_message || {};
// 2 ต.ค. 69: user สร้างคลิป Veo เองใน Flow แล้ว Reply ข้อความคลิปของดีล (caption มี '#d <page_id>') ด้วยวิดีโอ → deal-video ประกอบ (ป้ายราคา/พากย์/เพลง) + ลง TikTok ตรง + ส่งคลิปผลกลับ
const dm = String(rep.caption || rep.text || '').match(/#d\s+([A-Za-z0-9_-]+)/);   // 3 ต.ค. 69: ข้อความ prompt (text) ก็มี #d แล้ว — user เคย Reply ที่ prompt แทนรูปแล้วระบบเงียบ
if (dm && chatId && msg.video && msg.video.file_id) {
  const TG_BOT = 'REPLACE_TELEGRAM_BOT_TOKEN';
  let reply;
  try {
    const f = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.telegram.org/bot' + TG_BOT + '/getFile', qs: { file_id: msg.video.file_id }, json: true, timeout: 30000 });
    const fileUrl = 'https://api.telegram.org/file/bot' + TG_BOT + '/' + f.result.file_path;
    const r = await this.helpers.httpRequest({ method: 'POST', url: 'http://deal-video:8080/render',
      body: { deal_id: dm[1], bg_video: fileUrl, voice: true,
              tiktok: { mode: 'sandbox', privacy: 'SELF_ONLY' },
              telegram: { url: 'https://api.telegram.org/bot' + TG_BOT + '/sendVideo', chat_id: String(chatId), caption: '🎬 ประกอบจากคลิปที่คุณส่ง — ลง TikTok แล้ว' } },
      json: true, timeout: 290000, ignoreHttpStatusErrors: true });
    const tk = (r && r.tiktok) || {};
    if (r && r.error) reply = '❌ ' + r.error;
    else reply = (tk.ok ? '✅ ลง TikTok แล้ว (' + (tk.mode || '') + '/' + (tk.privacy || '') + ')' : '❌ TikTok ไม่สำเร็จ: ' + (tk.error || 'unknown')) + (r && r.sent ? '' : ' · ส่งคลิปผลกลับไม่สำเร็จ') + (r && r.veo && r.veo.ok ? '' : ' · ใช้คลิปที่ส่งมาไม่ได้: ' + ((r && r.veo && r.veo.error) || '?'));
  } catch (e) { reply = '❌ ' + String((e && e.message) || e).slice(0, 120); }
  return [{ json: { text, chatId, url: null, source: null, origUrl: null, affNote: null, hasUrl: false, veoReply: reply, userClip: true } }];
}
const vm = String(rep.caption || '').match(/#veo\s+([A-Za-z0-9_-]+)/);
if (vm && chatId) {
  const t = String(msg.text || '').trim();
  const yes = /^(โพสต์|ลง|post|ok|โอเค|ตกลง|ใช่|y)/i.test(t), no = /^(ไม่|ทิ้ง|no|skip|ยกเลิก|n)/i.test(t);
  let reply;
  if (!yes && !no) reply = 'ตอบว่า "โพสต์" เพื่อลง TikTok หรือ "ไม่" เพื่อทิ้งคลิปนี้';
  else {
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'http://deal-video:8080/' + (yes ? 'publish' : 'discard'), body: { id: vm[1] }, json: true, timeout: 180000, ignoreHttpStatusErrors: true });
      const tk = (r && r.tiktok) || {};
      reply = yes ? ((r && r.ok) ? '✅ ลง TikTok แล้ว (' + (tk.mode || '') + '/' + (tk.privacy || '') + ') — ' + (r.name || '') : '❌ ลงไม่สำเร็จ: ' + ((r && (r.error || tk.error)) || 'unknown'))
                  : ((r && r.ok) ? '🗑 ทิ้งคลิปแล้ว — ' + (r.name || '') : '❌ ' + ((r && r.error) || 'unknown'));
    } catch (e) { reply = '❌ ' + String((e && e.message) || e).slice(0, 120); }
  }
  return [{ json: { text, chatId, url: null, source: null, origUrl: null, affNote: null, hasUrl: false, veoReply: reply } }];
}
let url=(text.match(/https?:\/\/\S+/)||[null])[0];
const source=!url?null:(/tiktok\.com/i.test(url)?'tiktok':(/lazada\.|lzd\.co/i.test(url)?'lazada':(/shopee\.|shp\.ee/i.test(url)?'shopee':null)));

// 27 ก.ย. 69: ลิงก์ Shopee ธรรมดา (shopee.co.th / th.shp.ee) → ขอลิงก์ affiliate จาก deal-video /afflink (Shopee Affiliate Open API)
// แปลงไม่ได้/บริการล่ม = ใช้ลิงก์เดิมต่อ (affNote บอกเหตุผล) — ห้ามให้ขั้นนี้ทำ intake ล้ม
let affNote = null, origUrl = null;
if (url && source === 'shopee') {
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url: 'http://deal-video:8080/afflink', body: { url }, json: true, timeout: 20000 });
    if (r && r.ok && r.link) { if (r.link !== url) { origUrl = url; url = r.link; } }
    else affNote = (r && r.reason) || 'afflink failed';
  } catch (e) { affNote = 'afflink error: ' + String((e && e.message) || e).slice(0, 80); }
}

// 5 ต.ค. 69: /deal จาก Discord ส่ง update แบบเดียวกับ Telegram + discord.channel → ตอบกลับทาง Discord (node 'Via Discord?')
const dc = (b.discord && b.discord.channel) ? String(b.discord.channel) : null;
return [{json:{text,chatId,url,source,origUrl,affNote,hasUrl:!!(url&&chatId),dc}}];

const resp=$input.first().json;
let parsed={};
try{const t=(resp.content||[{}])[0].text||'';parsed=JSON.parse((t.match(/\{[\s\S]*\}/)||['{}'])[0]);}catch(e){}
const info=$('Extract').first().json;
const name=(parsed.name||'').trim()||null;
const sale=Number(parsed.sale_price)||null;
const full=Number(parsed.full_price)||sale;   // 8 ต.ค. 69 user: ตรวจแล้วไม่มีราคาเต็มจริง → ใส่เท่าราคาลด (ไม่มีบรรทัดราคาเดิม/% เพราะทุกจุดเช็ค full>sale)
const cats=["บ้าน", "gadget", "ความงาม", "แฟชั่น", "อาหาร", "กาแฟ", "รถ", "สัตว์เลี้ยง", "Fitness", "เครื่องดนตรี", "อื่นๆ"]   // 5 ต.ค. 69: เพิ่ม เครื่องดนตรี;   // 28 ก.ย. 69: = ตัวเลือก หมวด ใน Notion ทั้งหมด (เดิมมี 5 ตัว → 'อาหาร' ที่ Claude ตอบถูกโดนตัดเป็น 'อื่นๆ' ทั้งคิว)
const cat=cats.includes(parsed.category)?parsed.category:'อื่นๆ';
const complete=!!name;
const props={
  'สินค้า':{title:[{text:{content:name||('(รอเติมชื่อ) ดีลจาก '+(info.source||'ร้านค้า'))}}]},
  'ลิงก์Affiliate':{url:info.url},
  'หมวด':{select:{name:cat}},
  'สถานะ':{select:{name:complete?'ใหม่':'รอตรวจ'}}
};
if(full)props['ราคาเต็ม']={number:full};
if(sale)props['ราคาลด']={number:sale};
if(info.source)props['แหล่ง']={select:{name:info.source}};
const missing=[];
if(!name)missing.push('ชื่อสินค้า');
if(!sale)missing.push('ราคาลด');
if(!full)missing.push('ราคาเต็ม');
return [{json:{payload:{parent:{database_id:'589f80403f534993b49fd9fdd4d292ff'},properties:props},chatId:info.chatId,name,full,sale,cat,complete,missing,source:info.source}}];

const page=$input.first().json;
const b=$('Build Payload').first().json;
const rowUrl=page.url||'';
let text;
if(b.complete){
  // 5 ต.ค. 69: ไม่มีราคา (หน้าร้านไม่ให้ og ราคา) เคยขึ้น '฿null' · user: ปกติไม่ต้องส่งราคา → ไม่มีราคา = ไม่มีบรรทัดราคา ไม่ขอให้เติม
  const price=b.sale?('฿'+b.sale+(b.full?' (เต็ม ฿'+b.full+')':'')+' • '):(b.full?'฿'+b.full+' • ':'');
  text='✅ เพิ่มดีลแล้ว: '+b.name+'\n'+price+'หมวด '+b.cat+'\nบันทึกใน Notion สถานะ "ใหม่" — รอบถัดไปเขียนแคปชันแล้วโพสต์อัตโนมัติครับ';
}else{
  text='⚠️ เพิ่มแถวแล้วแต่ข้อมูลไม่ครบ ขาด: '+b.missing.join(', ')+'\nเปิดแถวเติมข้อมูลแล้วเปลี่ยนสถานะเป็น "ใหม่":\n'+rowUrl+'\n\n'+(b.source==='tiktok'?'ทริค TikTok: หน้าสินค้า TikTok บล็อกบอต ดึงชื่อ/รูปอัตโนมัติไม่ได้ ต้องพิมพ์ชื่อ+ราคามากับลิงก์ เช่น "หูฟัง XYZ 590 บาท <ลิงก์>"':'ทริค: แชร์จากแอป Shopee/Lazada โดยตรง หรือพิมพ์ราคาต่อท้ายลิงก์ เช่น "เต็ม 900 ลด 300"');
}

// หมายเหตุลิงก์ affiliate (27 ก.ย. 69)
try { const ex=$('Extract').first().json; if (ex.origUrl) text += '\n🔗 แปลงเป็นลิงก์ affiliate ให้แล้ว'; else if (ex.affNote && ex.source==='shopee') text += '\n⚠️ ลิงก์นี้ยังไม่ใช่ลิงก์ affiliate (ค่าคอมจะไม่เข้า) — ในแอป Shopee ให้กดแชร์ด้วยปุ่ม "แชร์และรับค่าคอม" (ลิงก์จะขึ้นต้น s.shopee.co.th) แล้วส่งมาใหม่ได้เลย'; } catch (e) {}
return [{json:{chat_id:b.chatId,text,disable_web_page_preview:true}}];

const i=$input.first().json;
if(!i.chatId)return [];
return [{json:{chat_id:i.chatId,text:'ส่งลิงก์ดีล Shopee มาได้เลยครับ 🛒\nแนะนำ: แชร์จากแอป Shopee โดยตรง (มีชื่อสินค้าติดมา) แล้วพิมพ์ราคาต่อท้าย เช่น "เต็ม 900 ลด 300" + ใส่ลิงก์ affiliate ของคุณ',disable_web_page_preview:true}}];

const info=$('Extract').first().json;
let og='';
try{
  const j=$input.first().json;
  const html=typeof j.data==='string'?j.data:(typeof j.body==='string'?j.body:'');
  const pick=re=>{const m=html.match(re);return m?m[1]:'';};
  og=pick(/property="og:title"[^>]*content="([^"]{0,300})"/)
   ||pick(/content="([^"]{0,300})"[^>]*property="og:title"/)
   ||pick(/<title[^>]*>([^<]{0,300})/);
  og=og.replace(/\s*\|\s*Shopee Thailand\s*$/,'').replace(/\s*[|-]\s*Lazada[^|]*$/i,'').trim();
}catch(e){}
const text=info.text+(og?'\nog:title: '+og:'');
return [{json:{text}}];

const q=$input.first().json;
const info=$('Extract').first().json;
const nums=(info.text.match(/\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?/g)||[]).map(x=>Number(String(x).replace(/,/g,''))).filter(n=>n>0&&n<1000000);
const row=(q.results||[])[0];
if(!row||!nums.length)return [{json:{doPatch:false}}];
const sale=Math.min.apply(null,nums);
const full=nums.length>1?Math.max.apply(null,nums):null;
const props={'ราคาลด':{number:sale},'สถานะ':{select:{name:'ใหม่'}}};
if(full&&full!==sale)props['ราคาเต็ม']={number:full};
const title=((row.properties['สินค้า']||{}).title||[]).map(t=>t.plain_text).join('');
return [{json:{doPatch:true,pageId:row.id,payload:{properties:props},title,sale,full}}];

const a=$('Apply Prices').first().json;
const text='✅ เติมราคาแล้ว: '+a.title.slice(0,60)+'\n฿'+a.sale+(a.full?' (เต็ม ฿'+a.full+')':'')+'\nสถานะ "ใหม่" — เข้าคิวเขียนแคปชันรอบถัดไปครับ';
return [{json:{chat_id:$('Extract').first().json.chatId,text,disable_web_page_preview:true}}];
